input.command:
PW=$(cat ~/.config/opencode/ocremote-password 2>/dev/null); echo "pw_len=${#PW}";
echo "=== procs opencode ==="; ps -eo pid,ppid,etime,args | grep -E '[o]pencode' | head -20;
echo "=== :4097 ==="; curl -s -m 5 -u "opencode:$PW" 'http://127.0.0.1:4097/api/info'; echo;
echo "=== :4096 ==="; curl -s -m 5 -u "opencode:$PW" 'http://127.0.0.1:4096/api/info'; echo;
echo "=== service.json ==="; cat ~/.config/opencode/service.json 2>/dev/null; echo;
echo "=== sqlite3? ==="; which sqlite3 || echo none;
echo "=== tables ==="; sqlite3 ~/.local/share/opencode/opencode.db ".tables" 2>&1 | head -5;
echo "=== sessions count ==="; curl -s -m 5 -u "opencode:$PW" 'http://127.0.0.1:4096/api/session?directory=/home/utilisateur' | head -c 300
